using System.Text;
using Penny.Backend.Application.Authentication;
using Shouldly;
using Xunit;

namespace Penny.Backend.UnitTests.Authentication;

public sealed class LegacyPasswordHasherTests
{
    // Generated by the legacy server's `security.hashPassword` (Node crypto.scrypt).
    private const string NodeSalt = "5f1c0e7a9b3d2468ace0f1357924680b";
    private const string NodePassword = "imported account password";
    private const string NodeHash =
        "6d4347584d1b837f80c695dc3f951ee36ebae6ff975402cba940f8a1c9b2574b5ba24380bd1a1de4d757032e9d6ed1f00131af295fd99083028916b841e48058";
    private const string UnicodeSalt = "0123456789abcdef0123456789abcdef";
    private const string UnicodePassword = "pässwörd 東京 👩‍👩‍👧";
    private const string UnicodeHash =
        "b50207e04fc01c8f5b1a9c47bf7683eaa61546a0a7a7f495577dcce79b1016d99cf6c9dc3358ecf428019173b7afb36f836f7be7c05f977d4894ce758e0ab571";

    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    [Theory]
    [InlineData(
        "",
        "",
        16,
        1,
        1,
        "77d6576238657b203b19ca42c18a0497f16b4844e3074ae8dfdffa3fede21442fcd0069ded0948f8326a753a0fc81f17e8d3e0fb2e0d3628cf35e20c38d18906"
    )]
    [InlineData(
        "password",
        "NaCl",
        1024,
        8,
        16,
        "fdbabe1c9d3472007856e7190d01e9fe7c6ad7cbc8237830e77376634b3731622eaf30d92e22a3886ff109279d9830dac727afb94a83ee6d8360cbdfa2cc0640"
    )]
    [InlineData(
        "pleaseletmein",
        "SodiumChloride",
        16384,
        8,
        1,
        "7023bdcb3afd7348461c06cd81fd38ebfda8fbba904f8e3ea9b543f6545da1f2d5432955613f0fcf62d49705242a9af9e61e85dc0d651e40dfcf017b45575887"
    )]
    public void whenRfc7914VectorDerived_Derive_ShouldMatchPublishedKey(
        string password,
        string salt,
        int cost,
        int blockSize,
        int parallelization,
        string expected
    )
    {
        var key = LegacyScrypt.Derive(
            Encoding.UTF8.GetBytes(password),
            Encoding.UTF8.GetBytes(salt),
            cost,
            blockSize,
            parallelization,
            64
        );
        Convert.ToHexStringLower(key).ShouldBe(expected);
    }

    [Theory]
    [InlineData(NodePassword, NodeSalt, NodeHash)]
    [InlineData(UnicodePassword, UnicodeSalt, UnicodeHash)]
    public async Task whenLegacyNodeHashStored_HashAndVerify_ShouldReproduceAndAcceptIt(
        string password,
        string salt,
        string hash
    )
    {
        using var hasher = new LegacyPasswordHasher();
        (await hasher.HashAsync(password, salt, Ct)).ShouldBe(hash);
        (await hasher.VerifyAsync(password, salt, hash, Ct)).ShouldBeTrue();
        (await hasher.VerifyAsync(password, salt, hash.ToUpperInvariant(), Ct)).ShouldBeTrue();
        (await hasher.VerifyAsync(password + " ", salt, hash, Ct)).ShouldBeFalse();
        (await hasher.VerifyAsync(password, salt.ToUpperInvariant(), hash, Ct)).ShouldBeFalse();
    }

    [Theory]
    [InlineData("")]
    [InlineData("not-hex")]
    [InlineData(NodeHash + "0")]
    [InlineData(NodeHash + "zz")]
    public async Task whenStoredHashUnusualOrUnusable_Verify_ShouldMatchNodeHexDecoding(
        string stored
    )
    {
        using var hasher = new LegacyPasswordHasher();
        // Node decodes the leading valid hex pairs, so trailing junk after the
        // 64-byte key still verifies; empty (OIDC-only) and non-hex never do.
        (await hasher.VerifyAsync(NodePassword, NodeSalt, stored, Ct)).ShouldBe(
            stored.StartsWith(NodeHash, StringComparison.Ordinal)
        );
    }

    [Theory]
    [InlineData("abZZcd", "ab")]
    [InlineData("abc", "ab")]
    [InlineData("", "")]
    public void whenHexHasInvalidTail_DecodeHexPrefix_ShouldDecodeLeadingPairs(
        string value,
        string expected
    ) => Convert.ToHexStringLower(LegacyPasswordHasher.DecodeHexPrefix(value)).ShouldBe(expected);
}
